'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const DIM={D1:'Ausencia o uso inadecuado de equipos de protección personal',D2:'Aproximación a áreas restringidas',D3:'Posturas y posiciones inseguras',D4:'Trabajo cerca de vehículos y equipos en movimiento'};
const SHORT={D1:'Equipos de protección personal',D2:'Áreas restringidas',D3:'Posturas y posiciones',D4:'Vehículos y equipos en movimiento'};
const defaults={task:'',responsible:'',validated:false,viewOK:false,gear:{casco:true,chaleco:true,ocular:true,guantes:true},confidence:.5,dwell:1.5,maxGap:5,release:2,trunk:0,arm:0,knee:0,distance:0,speed:0,radius:0,zones:{},calibration:null,geometryValid:false};
let cfg=structuredClone(defaults),events=[],db,engine=null,backend='',running=false,stream=null,mediaURL=null,mode=null,sourceName='',session=crypto.randomUUID(),segment=0,lastFrame=null,lastResult=null,drawMode=null,points=[],filter='all',ipTimer=null,autoTimer=null,busy=false,connectionGeneration=0;
const book=new CupriRules.Episodes(),video=$('#video'),ip=$('#ip-image'),canvas=$('#overlay'),ctx=canvas.getContext('2d');
try{cfg={...defaults,...JSON.parse(localStorage.getItem('cupri-profile')||'{}'),geometryValid:false};}catch{}
const statusName={pending:'Pendiente',confirmed:'Confirmado',discarded:'Descartado',uncertain:'Indeterminado',duplicate:'Duplicado'};
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,6500);}
function text(node,value){node.textContent=value;return node;}
function el(tag,cls,content){const n=document.createElement(tag);if(cls)n.className=cls;if(content!==undefined)n.textContent=content;return n;}
function saveProfile(){try{localStorage.setItem('cupri-profile',JSON.stringify({...cfg,geometryValid:false}));}catch{toast('No se pudo guardar el perfil. Exporta el proyecto.');}renderProfile();}
function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('cuprivision-local',1);req.onupgradeneeded=()=>req.result.createObjectStore('events',{keyPath:'id'});req.onerror=()=>reject(req.error);req.onsuccess=()=>resolve(req.result);});}
function dbSave(event){if(!db)return;const tx=db.transaction('events','readwrite');tx.objectStore('events').put(structuredClone(event));tx.onerror=()=>{text($('#storage-status'),'Guardado fallido: exporta el proyecto');toast('No hay espacio para guardar. Exporta tu proyecto antes de cerrar.');};}
function remember(event){const at=events.findIndex(e=>e.id===event.id),old=at>=0?events[at]:null;const merged={...old,...event};if(!merged.evidence&&frameReady())merged.evidence=capture(800,.65);if(!merged.session){merged.session=session;merged.segment=segment;merged.source=sourceName;merged.task=cfg.task;merged.profile=structuredClone(cfg);merged.models=structuredClone(engine?.models||{});}if(at>=0)events[at]=merged;else events.unshift(merged);dbSave(merged);}
function renderMetrics(){const counts=CupriRules.count(events),host=$('#metrics');host.replaceChildren();for(const d of Object.keys(DIM)){const card=el('article','metric'),top=el('div','metric-top');top.append(el('span','dim-badge',d),el('span','mini',events.filter(e=>e.status==='pending'&&e.dimensions[d]).length+' pendientes'));card.append(top,el('h3','',SHORT[d]));const bottom=el('div','metric-bottom');bottom.append(el('span','metric-number',counts[d]),el('small','','confirmados'));card.append(bottom);host.append(card);}text($('#nav-count'),events.length);}
function renderEvents(){renderMetrics();text($('#event-count'),events.length);const list=events.filter(e=>filter==='all'||e.status===filter).sort((a,b)=>b.created.localeCompare(a.created));const tbody=$('#event-rows');tbody.replaceChildren();$('#empty-events').hidden=!!list.length;for(const e of list){const tr=el('tr'),id=el('td','',e.id.slice(0,8).toUpperCase());id.append(el('small','',`${e.start.toFixed(1)}–${e.end.toFixed(1)} s · ID ${e.track}`));const dims=el('td','',Object.keys(e.dimensions).join(' · '));if(e.principal)dims.append(el('small','','Principal: '+e.principal));const origin=el('td','',e.origin==='manual'?'Manual':'Automático');origin.append(el('small','',e.source||''));const state=el('td');state.append(el('span','status '+e.status,statusName[e.status]));const action=el('td'),button=el('button','text-btn',e.closed?'Revisar →':'En curso');button.disabled=!e.closed;button.onclick=()=>reviewEvent(e.id);action.append(button);tr.append(id,dims,origin,state,action);tbody.append(tr);}}
function renderProfile(){text($('#task-name'),cfg.task||'Sin configurar');text($('#profile-summary'),cfg.validated?'Criterios revisados · '+cfg.responsible:'Define y revisa los criterios de esta tarea.');$('#geometry-valid').checked=cfg.geometryValid;text($('#geometry-status'),Object.keys(cfg.zones).length+' zonas · '+(cfg.calibration?'Calibración configurada':'Sin calibración métrica'));const host=$('#profile-overview');host.replaceChildren();for(const d of Object.keys(DIM)){const a=el('article');a.append(el('span','dim-badge',d),el('h3','',DIM[d]));const desc=d==='D1'?'EPP exigido: '+Object.entries(cfg.gear).filter(x=>x[1]).map(x=>x[0]).join(', '):d==='D2'?'Zonas restringidas y de aproximación. Autorizaciones por trayectoria temporal.':d==='D3'?`Tronco: ${cfg.trunk||'sin definir'}°. Brazo: ${cfg.arm||'sin definir'}°. Rodilla: ${cfg.knee||'sin definir'}°. Vista 2D: ${cfg.viewOK?'revisada':'pendiente'}.`:`Separación: ${cfg.distance||'sin definir'} m. Movimiento: ${cfg.speed||'sin definir'} m/s. Radio envolvente: ${cfg.radius||'sin definir'} m.`;a.append(el('p','',desc));host.append(a);}updateButtons();}
function view(name){$('#monitor-view').hidden=name!=='monitor';$('#profile-view').hidden=name!=='profile';$('#events-section').hidden=name==='profile';text($('#page-title'),name==='monitor'?'Monitoreo de seguridad':name==='events'?'Revisión de eventos':'Criterios y zonas');text($('#breadcrumb-current'),name==='monitor'?'Monitoreo':name==='events'?'Eventos':'Criterios y zonas');$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));}
$$('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));renderEvents();});
function modal(title,html,handler,label='Guardar'){text($('#dialog-title'),title);$('#dialog-content').innerHTML=html;text($('#dialog-submit'),label);$('#dialog-submit').hidden=!handler;$('#dialog').showModal();$('#dialog-form').onsubmit=async e=>{e.preventDefault();try{const done=await handler(new FormData(e.target));if(done!==false)$('#dialog').close();}catch(err){toast(err.message);}};}
$('#close-dialog').onclick=$('#cancel-dialog').onclick=()=>$('#dialog').close();
function input(name,label,type='number',extra=''){return `<label>${label}<input name="${name}" type="${type}" ${extra}></label>`;}
function profileDialog(){if(running)stopAnalysis('Edición de criterios');const fields=[['confidence','Confianza del detector','min="0.1" max="0.95" step="0.05"'],['dwell','Persistencia de evidencia (s)','min="0.1" max="120" step="0.1"'],['maxGap','Máximo intervalo sin observación (s)','min="0.5" max="60" step="0.5"'],['release','Cierre sin evidencia (s)','min="0.1" max="120" step="0.1"'],['trunk','D3 · Tronco: ángulo máximo (°)','min="0" max="180" step="1"'],['arm','D3 · Brazo: elevación máxima (°)','min="0" max="180" step="1"'],['knee','D3 · Rodilla: ángulo mínimo (°)','min="0" max="180" step="1"'],['distance','D4 · Separación de seguridad (m)','min="0" max="100" step="0.1"'],['speed','D4 · Umbral de movimiento (m/s)','min="0" max="50" step="0.01"'],['radius','D4 · Radio envolvente máximo (m)','min="0" max="100" step="0.1"']];modal('Criterios de la tarea',`<div class="form-grid">${input('task','Tarea observada','text','required maxlength="150"')}${input('responsible','Responsable de los criterios','text','required maxlength="100"')}<fieldset><legend>D1 · EPP exigido por la tarea</legend>${Object.keys(cfg.gear).map(g=>`<label class="check"><input type="checkbox" name="gear-${g}">${g==='ocular'?'Protección ocular':g[0].toUpperCase()+g.slice(1)}</label>`).join('')}</fieldset>${fields.map(([n,l,a])=>input(n,l,'number',a+' required')).join('')}<p class="form-note span2">Cero desactiva una regla de D3 o D4. Los umbrales deben corresponder al trabajo observado; no son límites normativos universales.</p><label class="check span2"><input type="checkbox" name="viewOK">La vista es adecuada para los criterios posturales 2D.</label><label class="check span2"><input type="checkbox" name="validated">Los criterios y requisitos fueron revisados para esta tarea.</label></div>`,async f=>{const next={...cfg,task:f.get('task').trim(),responsible:f.get('responsible').trim(),validated:f.has('validated'),viewOK:f.has('viewOK')};for(const [n]of fields){next[n]=Number(f.get(n));if(!Number.isFinite(next[n]))throw Error('Valor numérico inválido.');}next.gear=Object.fromEntries(Object.keys(cfg.gear).map(g=>[g,f.has('gear-'+g)]));cfg=next;saveProfile();await resetEngine();toast('Criterios guardados.');});for(const k of ['task','responsible',...fields.map(x=>x[0])])$(`#dialog [name="${k}"]`).value=cfg[k];for(const k of ['validated','viewOK'])$(`#dialog [name="${k}"]`).checked=cfg[k];for(const g of Object.keys(cfg.gear))$(`#dialog [name="gear-${g}"]`).checked=cfg.gear[g];}
$('#profile-btn').onclick=$('#edit-profile-full').onclick=profileDialog;
async function api(path,data,timeout=15000){if(!backend)throw Error('Conecta primero el motor local.');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeout);try{const res=await fetch(backend+path,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data),signal:controller.signal});const value=await res.json();if(!res.ok)throw Error(value.detail||'Error del motor local');return value;}catch(e){if(e.name==='AbortError')throw Error('El motor no respondió a tiempo. Comprueba la consola local.');throw e;}finally{clearTimeout(timer);}}
function renderEngine(){const online=!!engine;text($('#engine-label'),online?(engine.loading?'Cargando modelos':engine.pose?'Motor conectado':'Conectado · sin modelos'):'Motor sin conectar');$('#engine-dot').classList.toggle('online',online);text($('#engine-note'),online?(engine.pose?'Pose lista. EPP: '+(engine.ppe?'disponible':'sin cargar')+'. Equipos: '+(engine.machines?'disponible':'sin cargar')+'.':'Abre la conexión para cargar los modelos.'): 'Conecta el motor local para analizar imágenes.');text($('#connect-btn'),online?'Estado y modelos ↗':'Conectar motor local ↗');updateButtons();}
function connectionDialog(){modal('Motor local de análisis',`<p class="form-note">Descarga el programa, ejecuta <b>INICIAR_WINDOWS.bat</b> y abre la dirección local que aparece. El motor procesa los fotogramas en tu computadora. Si el navegador bloquea esta conexión desde la página privada, utiliza directamente <b>http://127.0.0.1:8765</b>.</p><label class="small-label">Dirección local<input id="backend-url" name="url" type="url" required></label><div id="connection-status" class="capability-list"></div><button type="button" id="load-models" class="outline" style="margin-top:12px">Cargar / reintentar modelos</button>`,async f=>{const u=new URL(f.get('url'));if(!['localhost','127.0.0.1','[::1]'].includes(u.hostname))throw Error('Usa la dirección del motor local.');backend=u.origin;engine=await api('/api/status');renderEngine();text($('#connection-status'),describeEngine());toast('Conexión establecida.');return false;},'Conectar');$('#backend-url').value=backend||'http://127.0.0.1:8765';text($('#connection-status'),describeEngine());$('#load-models').onclick=async()=>{try{if(!backend)throw Error('Conecta primero el motor.');await api('/api/load',{});toast('Descarga y carga iniciadas. Puedes seguir usando la interfaz.');pollEngine();}catch(e){toast(e.message);}};}
function describeEngine(){if(!engine)return 'Sin conexión. No se han generado detecciones.';return `Pose: ${engine.pose?'lista':'no disponible'} · EPP: ${engine.ppe?'listo':'no disponible'} · Equipos: ${engine.machines?'listo':'no disponible'}. ${engine.loading?'Cargando… ':''}${(engine.errors||[]).join(' ')} ${engine.classes? 'Clases EPP: '+engine.classes.join(', '):''}`;}
async function pollEngine(){try{engine=await api('/api/status');renderEngine();if($('#connection-status'))text($('#connection-status'),describeEngine());if(engine.loading)setTimeout(pollEngine,2000);}catch(e){engine=null;renderEngine();toast('Conexión perdida: '+e.message);}}
$('#connect-btn').onclick=connectionDialog;
async function resetEngine(){segment++;lastResult=null;if(backend&&engine){try{await api('/api/reset',{});}catch{engine=null;renderEngine();}}}
function frameReady(){return mode==='ip'?ip.complete&&ip.naturalWidth>0:video.readyState>=2;}
function imageSize(){return mode==='ip'?[ip.naturalWidth,ip.naturalHeight]:[video.videoWidth,video.videoHeight];}
function capture(width=960,quality=.7){if(!frameReady())return null;const [w,h]=imageSize(),c=document.createElement('canvas');c.width=Math.min(width,w);c.height=Math.round(c.width*h/w);c.getContext('2d').drawImage(mode==='ip'?ip:video,0,0,c.width,c.height);return c.toDataURL('image/jpeg',quality);}
function updateButtons(){$('#analyze-btn').disabled=running||busy||!frameReady()||!engine?.pose||!cfg.validated;$('#stop-btn').disabled=!running;$('#draw-btn').disabled=!frameReady();}
function stopAnalysis(reason='Detenido por el operador'){running=false;clearTimeout(autoTimer);for(const e of book.close(reason))remember(e);text($('#analysis-state'),'Análisis detenido');text($('#source-tag'),mode?'CONECTADO':'EN ESPERA');updateButtons();renderEvents();}
async function releaseSource(){connectionGeneration++;stopAnalysis('Cambio de fuente');clearTimeout(ipTimer);if(mode==='ip'&&backend&&engine){try{await api('/api/camera/close',{});}catch{}}if(stream){stream.getTracks().forEach(t=>t.stop());stream=null;}video.pause();video.srcObject=null;video.removeAttribute('src');video.load();if(mediaURL){URL.revokeObjectURL(mediaURL);mediaURL=null;}ip.removeAttribute('src');mode=null;cfg.geometryValid=false;session=crypto.randomUUID();await resetEngine();lastFrame=null;lastResult=null;renderProfile();}
function sourceUI(name){sourceName=name;text($('#source-name'),name);$('#empty-camera').hidden=true;video.hidden=mode==='ip';ip.hidden=mode!=='ip';text($('#source-info'),mode==='video'?'Vídeo local. El análisis sigue el tiempo del archivo.':mode==='webcam'?'Webcam activa. Puedes detenerla con Nueva observación.':'Cámara recibida por el motor local.');text($('#source-tag'),'CONECTADO');$$('.source-tabs button').forEach(b=>b.classList.remove('selected'));$(mode==='video'?'#upload-btn':mode==='webcam'?'#webcam-btn':'#ip-btn').classList.add('selected');view('monitor');}
$('#upload-btn').onclick=$('#empty-upload').onclick=()=>$('#video-file').click();$('#video-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;await releaseSource();mode='video';mediaURL=URL.createObjectURL(file);video.src=mediaURL;video.controls=true;sourceUI(file.name);video.load();e.target.value='';};
video.onloadeddata=()=>{updateButtons();};video.onerror=()=>toast('Este formato no se puede reproducir. Usa un MP4 H.264 o WebM compatible.');video.onended=()=>stopAnalysis('Fin del vídeo');video.onseeking=()=>{if(running)stopAnalysis('Salto en el vídeo');resetEngine();};
$('#webcam-btn').onclick=async()=>{try{if(!navigator.mediaDevices?.getUserMedia)throw Error('La webcam requiere un navegador compatible y una página segura.');await releaseSource();stream=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:1280},height:{ideal:720}},audio:false});mode='webcam';video.srcObject=stream;video.muted=true;video.controls=false;sourceUI('Webcam del navegador');await video.play();updateButtons();}catch(e){toast('No se pudo abrir la webcam: '+e.message);}};
$('#ip-btn').onclick=()=>{if(!engine){connectionDialog();return;}modal('Conectar cámara IP / RTSP',`<p class="form-note">La cámara debe ser accesible desde la computadora donde ejecutas el motor. La dirección se usa en memoria y no se guarda en el proyecto.</p>${input('source','Dirección RTSP','password','required placeholder="rtsp://usuario:clave@direccion/ruta" autocomplete="off"')}`,async f=>{await releaseSource();await api('/api/camera/open',{source:f.get('source')});mode='ip';sourceUI('Cámara IP');const generation=connectionGeneration;const read=async()=>{if(mode!=='ip'||generation!==connectionGeneration)return;try{const data=await api('/api/camera/frame');if(mode!=='ip'||generation!==connectionGeneration)return;ip.src=data.image;lastFrame=data.time;ip.onload=updateButtons;}catch(e){toast(e.message);stopAnalysis('Error de cámara');return;}ipTimer=setTimeout(read,150);};read();},'Conectar');};
$('#new-session').onclick=async()=>{await releaseSource();sourceName='';video.hidden=ip.hidden=true;$('#empty-camera').hidden=false;text($('#source-name'),'Sin fuente seleccionada');text($('#source-tag'),'EN ESPERA');text($('#clock'),'00:00');updateButtons();toast('Nueva observación. Los eventos anteriores se conservan.');};
function sourceTime(){return mode==='video'?video.currentTime:mode==='ip'?(lastFrame??performance.now()/1000):performance.now()/1000;}
async function analyze(){if(!running||busy)return;busy=true;const generation=connectionGeneration;try{if(!frameReady())throw Error('No hay un fotograma disponible.');if(mode==='video'&&video.paused){autoTimer=setTimeout(analyze,250);return;}const t=sourceTime(),frame=capture();const result=await api('/api/analyze',{image:frame,time:t,config:cfg},45000);if(!running||generation!==connectionGeneration)return;lastResult=result;for(const e of book.update(result.people,t,cfg,()=>crypto.randomUUID())){const old=events.find(x=>x.id===e.id);e.evidence=old?.evidence||frame;e.evidenceFrames={...(old?.evidenceFrames||{})};for(const d of Object.keys(e.dimensions))if(!e.evidenceFrames[d])e.evidenceFrames[d]=frame;remember(e);}renderEvents();text($('#processing-info'),`${result.people.length} personas · ${result.ms} ms / imagen`);text($('#analysis-state'),result.warnings?.length?result.warnings.join(' · '):'Analizando imágenes');}catch(e){stopAnalysis('Error del motor');toast(e.message);}finally{busy=false;updateButtons();if(running)autoTimer=setTimeout(analyze,150);}}
$('#analyze-btn').onclick=async()=>{if(!cfg.validated||!engine?.pose||!frameReady())return;try{await resetEngine();if(mode==='video')await video.play();running=true;text($('#source-tag'),'ANALIZANDO');updateButtons();analyze();}catch(e){toast(e.message);}};$('#stop-btn').onclick=()=>stopAnalysis();
function frameRect(){const [w,h]=imageSize(),W=canvas.width,H=canvas.height;if(!w||!h)return{x:0,y:0,w:W,h:H};const s=Math.min(W/w,H/h);return{x:(W-w*s)/2,y:(H-h*s)/2,w:w*s,h:h*s};}
function paint(){const stage=$('#stage'),dpr=window.devicePixelRatio||1;const w=stage.clientWidth*dpr,h=stage.clientHeight*dpr;if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;}ctx.clearRect(0,0,w,h);const r=frameRect();const pixel=p=>[r.x+p[0]*r.w,r.y+p[1]*r.h];function poly(points,color,close=true){if(!points.length)return;ctx.beginPath();points.forEach((p,i)=>{const [x,y]=pixel(p);i?ctx.lineTo(x,y):ctx.moveTo(x,y);});if(close)ctx.closePath();ctx.strokeStyle=color;ctx.lineWidth=2*dpr;ctx.stroke();if(close){ctx.fillStyle=color+'18';ctx.fill();}}
for(const [name,p]of Object.entries(cfg.zones))poly(p,({restricted:'#ffb46c',approach:'#e1d37a',position:'#a6a8ff'})[name]||'#b5df8b');if(cfg.calibration)poly(cfg.calibration.points.slice(0,4),'#6dd5cf');if(drawMode){poly(points,'#d8efa2',false);points.forEach((p,i)=>{const[x,y]=pixel(p);ctx.fillStyle='#d8efa2';ctx.beginPath();ctx.arc(x,y,4*dpr,0,7);ctx.fill();ctx.font=`${12*dpr}px sans-serif`;ctx.fillText(String(i+1),x+8*dpr,y-8*dpr);});}
if(lastResult&&running)for(const p of lastResult.people){const [x1,y1]=pixel(p.box.slice(0,2)),[x2,y2]=pixel(p.box.slice(2));ctx.strokeStyle=Object.keys(p.alerts).length?'#ffbd70':'#abd5ac';ctx.lineWidth=2*dpr;ctx.strokeRect(x1,y1,x2-x1,y2-y1);ctx.font=`${12*dpr}px sans-serif`;ctx.fillStyle=ctx.strokeStyle;ctx.fillText(`ID ${p.id} ${Object.keys(p.alerts).join(' ')}`,x1,Math.max(y1-7*dpr,15*dpr));}
if(mode==='video')text($('#clock'),`${String(Math.floor(video.currentTime/60)).padStart(2,'0')}:${String(Math.floor(video.currentTime%60)).padStart(2,'0')}`);requestAnimationFrame(paint);}
function cancelDraw(){drawMode=null;points=[];$('#stage').classList.remove('drawing');$('#draw-hint').hidden=true;$('#finish-draw').hidden=true;}
$('#draw-btn').onclick=()=>{if(!frameReady())return;stopAnalysis('Edición de geometría');if(mode==='video')video.pause();drawMode=$('#zone-kind').value;points=[];$('#stage').classList.add('drawing');$('#draw-hint').hidden=false;$('#finish-draw').hidden=false;text($('#draw-hint'),drawMode==='calibration'?'Marca 4 esquinas: (0,0), (ancho,0), (ancho,alto), (0,alto), y un 5.º punto independiente.':'Haz clic para añadir vértices. Guarda al terminar. Esc cancela.');};
canvas.onclick=e=>{if(!drawMode)return;const b=canvas.getBoundingClientRect(),r=frameRect(),x=(e.clientX-b.left)*canvas.width/b.width,y=(e.clientY-b.top)*canvas.height/b.height;const p=[(x-r.x)/r.w,(y-r.y)/r.h];if(p.some(v=>v<0||v>1))return;if(drawMode==='calibration'&&points.length>=5)return;points.push(p);};
function convex(p){if(p.length<3)return false;let sign=0;for(let i=0;i<p.length;i++){const a=p[i],b=p[(i+1)%p.length],c=p[(i+2)%p.length],z=(b[0]-a[0])*(c[1]-b[1])-(b[1]-a[1])*(c[0]-b[0]);if(Math.abs(z)<1e-7)return false;if(!sign)sign=Math.sign(z);else if(sign!==Math.sign(z))return false;}return true;}
$('#finish-draw').onclick=()=>{if(!drawMode)return;if(drawMode==='calibration'){if(points.length!==5||!convex(points.slice(0,4))){toast('Marca cuatro esquinas ordenadas de un cuadrilátero convexo y el quinto punto.');return;}const selected=structuredClone(points);modal('Medidas de calibración',`<p class="form-note">Mide un rectángulo real en un suelo plano. El quinto punto comprueba la transformación y debe estar dentro del rectángulo. Mover la cámara invalida la calibración.</p><div class="form-grid">${[['width','Ancho real (m)'],['height','Alto real (m)'],['checkX','X del quinto punto (m)'],['checkY','Y del quinto punto (m)'],['tolerance','Error máximo admisible (m)']].map(([k,l])=>input(k,l,'number','required min="0" step="0.001"')).join('')}</div>`,async f=>{const c={points:selected};for(const k of ['width','height','checkX','checkY','tolerance'])c[k]=Number(f.get(k));if(c.width<=0||c.height<=0||c.tolerance<=0)throw Error('Dimensiones y tolerancia deben ser mayores que cero.');if(!engine)throw Error('Conecta el motor para comprobar matemáticamente la calibración.');const checked=await api('/api/calibrate',c);cfg.calibration={...c,...checked};cfg.geometryValid=false;saveProfile();cancelDraw();toast('Calibración comprobada. Error: '+checked.error.toFixed(3)+' m.');});}else{if(!convex(points)){toast('Usa un polígono convexo, sin cruces ni vértices repetidos.');return;}cfg.zones[drawMode]=structuredClone(points);cfg.geometryValid=false;saveProfile();cancelDraw();toast('Zona guardada. Confirma el encuadre antes de evaluar.');}};
$('#clear-zone').onclick=()=>{stopAnalysis('Geometría modificada');const name=$('#zone-kind').value;if(name==='calibration')cfg.calibration=null;else delete cfg.zones[name];cfg.geometryValid=false;saveProfile();cancelDraw();};document.addEventListener('keydown',e=>{if(e.key==='Escape')cancelDraw();});$('#geometry-valid').onchange=e=>{cfg.geometryValid=e.target.checked;saveProfile();};
$('#authorize-btn').onclick=()=>{if(!engine){toast('Conecta el motor y analiza para obtener un ID visible.');return;}modal('Autorización temporal',`<p class="form-note">Se aplica al ID actual, durante esta sesión. No identifica a la persona y se anula al perder la trayectoria, cambiar de fuente o reiniciar el motor.</p><div class="form-grid">${input('id','ID visible','number','required min="1" step="1"')}${input('duration','Vigencia (segundos)','number','required min="1" max="3600" step="1"')}${input('responsible','Responsable de autorizar','text','required maxlength="100"')}</div>`,async f=>{await api('/api/authorize',{id:Number(f.get('id')),duration:Number(f.get('duration')),responsible:f.get('responsible')});toast('Autorización registrada para la trayectoria actual.');});};
$('#manual-btn').onclick=()=>{if(!frameReady()){toast('Carga un vídeo o conecta una cámara para adjuntar evidencia real.');return;}stopAnalysis('Observación manual');if(mode==='video')video.pause();const image=capture(),t=sourceTime();modal('Registrar observación manual',`<div class="form-grid"><label>Dimensión<select name="dimension">${Object.keys(DIM).map(d=>`<option>${d}</option>`).join('')}</select></label>${input('track','ID visible (0 si no existe)','number','required min="0" step="1" value="0"')}<label class="span2">Evidencia y contexto de la tarea<textarea name="notes" required maxlength="2000" placeholder="Describe lo que se observa, sin deducir lo que no es visible."></textarea></label></div><p class="form-note">Se guardará como pendiente de revisión con una captura del fotograma actual.</p>`,f=>{const dimension=f.get('dimension'),e={id:crypto.randomUUID(),track:Number(f.get('track')),start:t,end:t,dimensions:{[dimension]:[f.get('notes').trim()]},status:'pending',principal:'',closed:true,origin:'manual',created:new Date().toISOString(),notes:f.get('notes').trim(),reviewer:'',audit:[],evidence:image};remember(e);renderEvents();toast('Observación guardada con evidencia.');});};
function reviewEvent(id){const e=events.find(x=>x.id===id);if(!e)return;modal('Revisar evento '+id.slice(0,8).toUpperCase(),`<img class="evidence-image" id="review-evidence" alt="Fotograma de evidencia"><label class="small-label">Evidencia por dimensión<select id="review-frame"></select></label><p id="review-description" class="form-note"></p><div class="form-grid"><label>Resultado<select name="status">${Object.entries(statusName).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>Dimensión principal<select name="principal"><option value="">Seleccionar</option>${Object.keys(e.dimensions).map(d=>`<option>${d}</option>`).join('')}</select></label>${input('reviewer','Nombre del revisor','text','maxlength="100"')}${input('duplicateOf','ID completo del original (si es duplicado)','text')}<label class="span2">Justificación / tarea / condiciones del puesto<textarea name="notes" maxlength="4000"></textarea></label></div>`,f=>{const status=f.get('status'),reviewer=f.get('reviewer').trim(),principal=f.get('principal'),duplicate=f.get('duplicateOf').trim();if(status!=='pending'&&!reviewer)throw Error('Identifica al revisor.');if(status==='confirmed'&&!principal)throw Error('Selecciona una dimensión principal.');if(status==='duplicate'&&!events.some(x=>x.id===duplicate&&x.id!==id&&x.status==='confirmed'))throw Error('El original debe ser otro evento confirmado.');const audit={date:new Date().toISOString(),previous:e.status,status,reviewer,notes:f.get('notes'),principal,duplicateOf:duplicate};e.audit.push(audit);Object.assign(e,{status,reviewer,principal:status==='confirmed'?principal:'',notes:f.get('notes'),duplicateOf:status==='duplicate'?duplicate:''});dbSave(e);renderEvents();toast('Revisión guardada.');});$('#review-evidence').hidden=!e.evidence;if(e.evidence)$('#review-evidence').src=e.evidence;const frames=e.evidenceFrames||{};for(const d of Object.keys(e.dimensions))$('#review-frame').append(el('option','',d));$('#review-frame').onchange=()=>{const pic=frames[$('#review-frame').value]||e.evidence;if(pic)$('#review-evidence').src=pic;};$('#review-frame').onchange();text($('#review-description'),Object.entries(e.dimensions).map(([d,r])=>d+': '+r.join('; ')).join(' | '));for(const k of ['status','principal','reviewer','notes'])$(`#dialog [name="${k}"]`).value=e[k]||'';$('[name="duplicateOf"]').value=e.duplicateOf||'';}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
$('#csv-btn').onclick=()=>{const cols=['id','source','task','track','start','end','origin','status','principal','dimensions','reviewer','notes','duplicateOf'];const rows=[cols,...events.map(e=>cols.map(k=>k==='dimensions'?JSON.stringify(e.dimensions):e[k]??''))];download('CUPRIVISION_eventos.csv','\ufeff'+rows.map(r=>r.map(CupriRules.csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8');};
$('#project-export').onclick=()=>download('CUPRIVISION_proyecto.json',JSON.stringify({format:'cuprivision-1',exported:new Date().toISOString(),config:{...cfg,geometryValid:false},events},null,2),'application/json');$('#project-import-btn').onclick=()=>$('#project-import').click();
$('#project-import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>30*1024*1024)throw Error('Máximo 30 MB por proyecto.');const data=JSON.parse(await file.text());if(data.format!=='cuprivision-1'||!Array.isArray(data.events)||data.events.length>1000)throw Error('Proyecto no compatible.');for(const x of data.events){if(typeof x.id!=='string'||typeof x.created!=='string'||!Number.isFinite(x.start)||!Number.isFinite(x.end)||!Object.keys(statusName).includes(x.status)||!x.dimensions||Object.keys(x.dimensions).some(d=>!Object.hasOwn(DIM,d))||Object.values(x.dimensions).some(r=>!Array.isArray(r)||r.some(y=>typeof y!=='string'))||!Array.isArray(x.audit))throw Error('Un evento no tiene el formato esperado.');if(x.evidence&&!/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(x.evidence))throw Error('Evidencia no válida.');if(x.evidenceFrames&&Object.values(x.evidenceFrames).some(pic=>typeof pic!=='string'||!/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(pic)))throw Error('Evidencias por dimensión inválidas.');if(x.status==='confirmed'&&!x.dimensions[x.principal])throw Error('Dimensión principal inválida.');}stopAnalysis('Importación');for(const x of data.events)remember({...x,closed:true});renderEvents();toast('Eventos importados. Los criterios actuales se conservan; el perfil original está dentro de cada evento.');}catch(err){toast(err.message);}finally{e.target.value='';}};
$('#help-btn').onclick=()=>modal('Cómo usar CUPRIVISION',`<ol class="help-list"><li>Carga un vídeo o abre la webcam. Esto funciona sin el motor.</li><li>Para análisis automático, descarga el programa y ejecuta <b>INICIAR_WINDOWS.bat</b>. Abre <b>http://127.0.0.1:8765</b>.</li><li>Conecta el motor y pulsa <b>Cargar modelos</b>. La primera descarga necesita internet.</li><li>Configura tarea, EPP y criterios revisados. Dibuja y confirma las zonas.</li><li>Para D4, calibra con cuatro esquinas medidas y un quinto punto independiente. Define separación, velocidad y radio del equipo.</li><li>Inicia el análisis. Deténlo antes de revisar los eventos. Confirma únicamente evidencia suficiente y asigna una dimensión principal.</li><li>Exporta el proyecto para conservar capturas y revisiones. El CSV incluye también pendientes, identificados por su estado.</li></ol><p class="form-note">D1 usa clases explícitas del modelo: no detectar un equipo no equivale a detectar su ausencia. D3 utiliza geometría 2D por tarea. D4 estima distancias en el plano del suelo. No se ha validado precisión con grabaciones de tu investigación.</p><a class="download" href="downloads/CUPRIVISION.zip" download>↓ Descargar programa y documentación</a>`,null);
window.addEventListener('beforeunload',()=>{if(stream)stream.getTracks().forEach(t=>t.stop());});
(async()=>{try{db=await openDB();events=await new Promise((resolve,reject)=>{const req=db.transaction('events').objectStore('events').getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});for(const e of events)if(!e.closed){e.closed=true;e.closeReason='Sesión anterior interrumpida';dbSave(e);}}catch{toast('Almacenamiento local no disponible. Exporta antes de cerrar.');}renderProfile();renderEvents();paint();if(['127.0.0.1','localhost'].includes(location.hostname)){backend=location.origin;try{engine=await api('/api/status');renderEngine();}catch{}}})();
